python3 -I -c 'S="import sys,json,os,subprocess as R,tempfile,argparse,shutil\nfrom pathlib import Path\nQ=lambda:\"python3 -I -c %cS=%s;exec(S)%c \\\"$@\\\"\\n\"%(39,json.dumps(S),39)\nv=sys.argv[1:]\nif v==[\"self\"]:print(Q(),end=\"\");sys.exit()\nif v==[\"encode\"]:\n n=1\n for b in Q().encode():n=n*257+b+1\n print(hex(n)[2:]);sys.exit()\nif len(v)==2 and v[0]==\"decode\":\n n=int(v[1],16);a=[]\n while n>1:n,b=divmod(n-1,257);a.append(b)\n if n!=1:sys.exit(\"INVALID_G257\")\n sys.stdout.buffer.write(bytes(a[::-1]));sys.exit()\np=argparse.ArgumentParser(description=\"UTO Music Studio; other options go to voice.py\")\np.add_argument(\"--out\",default=\"music-output\");p.add_argument(\"--voice\",choices=[\"synth\",\"wav\"],default=\"synth\");p.add_argument(\"--lufs\",type=float,default=-14);p.add_argument(\"--true-peak\",type=float,default=-1.5)\na,v=p.parse_known_args(v)\nif not -24<=a.lufs<=-9 or not -6<=a.true_peak<=-1 or \"--midi-only\" in v:p.error(\"Invalid studio options\")\nf=Path(a.out).resolve()\nif f.exists():sys.exit(\"OUTPUT_EXISTS\")\nif not shutil.which(\"ffmpeg\"):sys.exit(\"Install FFmpeg first\")\ndef run(*v):R.run(v,check=True)\nwith tempfile.TemporaryDirectory(prefix=\"uto-music-\") as d:\n h=os.getenv(\"UTO_MUSIC_HOME\")\n if h:p=Path(h).resolve()\n else:\n  p=Path(d);run(\"git\",\"-C\",d,\"init\",\"-q\");run(\"git\",\"-C\",d,\"fetch\",\"--depth=1\",\"https://github.com/letsgo0226/UTO-Omega-Music.git\",\"097e3f427bb9ace540e69d1af827b62eb22d04ea\");run(\"git\",\"-C\",d,\"checkout\",\"-q\",\"--detach\",\"FETCH_HEAD\")\n run(sys.executable,str(p/\"voice.py\"),\"--voice\",a.voice,\"--out\",str(f),*v)\n run(sys.executable,str(p/\"studio.py\"),str(f),\"--lufs\",str(a.lufs),\"--true-peak\",str(a.true_peak))";exec(S)' "$@"
